mapper.select:
select mn.*
from Integrated_Work_Order_Dtl mn
left join Integrated_Work_Order iwo on mn.iwo_id = iwo.id
where mn.iwod_type = '01'
and iwo.Con_Construction_Id = #{conConstructionId}
and iwo.Con_Supervision_Id = #{conSupervisionId}
and iwo.State = 7

    and iwo.id != #{id}

and iwo.work_start_date = (
select MAX(sub_iwo.work_start_date)
from Integrated_Work_Order sub_iwo
where sub_iwo.Con_Construction_Id = #{conConstructionId}
and sub_iwo.Con_Supervision_Id = #{conSupervisionId}
)
